import React, { useState, useEffect, useRef } from 'react';
import { X, Terminal as TerminalIcon, Send, MessageSquare } from 'lucide-react';

interface ChatOverlayProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ChatOverlay: React.FC<ChatOverlayProps> = ({ isOpen, onClose }) => {
  const [history, setHistory] = useState<{type: 'system' | 'user' | 'ai', content: string}[]>([
    { type: 'system', content: 'INITIALIZING UPLINK...' },
    { type: 'system', content: 'CONNECTION ESTABLISHED.' },
    { type: 'ai', content: 'Welcome to the Rajeet Nair Interface Terminal (v2.4.0).' },
    { type: 'ai', content: 'Type "help" for commands or ask a question about my work.' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
        setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isOpen]);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [history, isOpen, isTyping]);

  const handleCommand = async () => {
    const cmd = input.trim();
    if (!cmd) return;

    setHistory(prev => [...prev, { type: 'user', content: cmd }]);
    setInput('');
    setIsTyping(true);

    // Simulated AI Response Logic
    setTimeout(() => {
      let response = '';
      const lowerCmd = cmd.toLowerCase();

      if (lowerCmd === 'help') {
        response = `AVAILABLE COMMANDS:
  - about       : Display profile summary
  - projects    : List mission critical systems
  - quick       : Navigate to Quick View Dashboard
  - contact     : Show communication channels
  - clear       : Clear terminal history
  - exit        : Close terminal session`;
      } else if (lowerCmd === 'clear') {
        setHistory([]);
        setIsTyping(false);
        return;
      } else if (lowerCmd === 'exit') {
        onClose();
        setIsTyping(false);
        return;
      } else if (lowerCmd === 'quick') {
         window.location.hash = '#/overview';
         response = "Navigating to Quick Overview Dashboard...";
      } else if (lowerCmd.includes('about')) {
         response = 'IDENTITY: Rajeet Nair\nROLE: Generative AI Engineer\nFOCUS: Agentic Systems, Production RAG, Python, and n8n.\nSTATUS: Online and Ready for Deployment.';
      } else if (lowerCmd.includes('projects')) {
         response = 'Retrieving Project Database...\n\n1. Nosta Social AI Agent\n2. Nosta Multi-RAG + OCR\n3. Invoice OCR & Cost Agent\n4. ML Warehouse Ops\n\nRun "project [id]" for details.';
      } else if (lowerCmd.includes('contact')) {
         response = 'COMMUNICATION CHANNELS:\n\n- Email: contact@rajeetnair.com\n- Location: Mumbai, India';
      } else {
        response = `Command received. \n\nAutomated Response: Rajeet is currently building production systems. For detailed inquiries, please use the email channel.`;
      }

      setHistory(prev => [...prev, { type: 'ai', content: response }]);
      setIsTyping(false);
    }, 600);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 sm:inset-auto sm:bottom-24 sm:right-8 w-full sm:w-[450px] h-full sm:h-[600px] z-[100] flex flex-col font-mono text-sm animate-fade-in shadow-[0_0_50px_rgba(0,0,0,0.8)]">
        {/* Terminal Container */}
        <div className="flex-grow bg-[#050505]/95 backdrop-blur-md border border-border sm:border-accent/30 flex flex-col relative overflow-hidden sm:rounded-lg">

            {/* Scanline & Glow Effects */}
            <div className="absolute inset-0 bg-scanline opacity-5 pointer-events-none z-10"></div>
            <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-accent/50 to-transparent z-20"></div>

            {/* Header */}
            <div className="bg-surface/80 p-3 flex justify-between items-center border-b border-white/10 shrink-0 relative z-30">
                <div className="flex items-center gap-2 text-accent px-1">
                    <TerminalIcon size={14} />
                    <span className="text-xs uppercase tracking-widest font-bold">Terminal_Uplink</span>
                </div>
                <button onClick={onClose} className="hover:text-accent text-textMuted transition-colors p-1">
                    <X size={16}/>
                </button>
            </div>

            {/* Output Area */}
            <div className="flex-grow p-4 overflow-y-auto no-scrollbar relative z-20" onClick={() => inputRef.current?.focus()}>
                {history.map((entry, idx) => (
                    <div key={idx} className={`mb-3 leading-relaxed break-words ${entry.type === 'user' ? 'text-white' : entry.type === 'system' ? 'text-textMuted text-xs' : 'text-accent'}`}>
                        {entry.type === 'user' ? (
                            <span className="flex gap-2">
                                <span className="text-accent/50 select-none">$</span>
                                <span>{entry.content}</span>
                            </span>
                        ) : entry.type === 'system' ? (
                            <span className="uppercase tracking-wider">>> {entry.content}</span>
                        ) : (
                            <span className="whitespace-pre-wrap">{entry.content}</span>
                        )}
                    </div>
                ))}
                {isTyping && (
                    <div className="flex gap-1 items-center text-accent/50 text-xs mt-2">
                        <span className="w-1.5 h-1.5 bg-accent animate-pulse"></span>
                        PROCESSING
                    </div>
                )}
                <div ref={scrollRef}></div>
            </div>

            {/* Input Area */}
            <div className="p-3 bg-surface/30 border-t border-white/10 shrink-0 relative z-30">
                <div className="flex items-center gap-2">
                    <span className="text-accent font-bold animate-pulse">></span>
                    <input 
                        ref={inputRef}
                        type="text" 
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleCommand()}
                        className="flex-grow bg-transparent border-none outline-none text-white font-mono placeholder-white/20"
                        placeholder="Enter command..."
                        autoComplete="off"
                    />
                    <button onClick={handleCommand} className="text-accent hover:text-white transition-colors">
                        <Send size={14} />
                    </button>
                </div>
            </div>
        </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { X, Terminal as TerminalIcon } from 'lucide-react';
import { Link } from 'react-router-dom';

export const Chat: React.FC = () => {
  const [history, setHistory] = useState<{type: 'system' | 'user' | 'ai', content: string}[]>([
    { type: 'system', content: 'INITIALIZING UPLINK...' },
    { type: 'system', content: 'CONNECTION ESTABLISHED.' },
    { type: 'ai', content: 'Welcome to the Rajeet Nair Interface Terminal (v2.4.0).' },
    { type: 'ai', content: 'Type "help" for available commands or simply ask a question.' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [history, isTyping]);

  // Focus input on mount
  useEffect(() => {
    // Slight delay to handle mobile keyboard animations
    setTimeout(() => {
        inputRef.current?.focus();
    }, 100);
  }, []);

  const handleCommand = async (cmd: string) => {
    const cleanCmd = cmd.trim();
    if (!cleanCmd) return;

    // Add user command to history
    setHistory(prev => [...prev, { type: 'user', content: cleanCmd }]);
    setInput('');
    setIsTyping(true);

    // Simulate processing delay
    setTimeout(() => {
      let response = '';
      const lowerCmd = cleanCmd.toLowerCase();

      if (lowerCmd === 'help') {
        response = `AVAILABLE COMMANDS:
  - about       : Display profile summary
  - projects    : List mission critical systems
  - contact     : Show communication channels
  - clear       : Clear terminal history
  - exit        : Close terminal session`;
      } else if (lowerCmd === 'clear') {
        setHistory([]);
        setIsTyping(false);
        return;
      } else if (lowerCmd === 'exit') {
        window.location.hash = '/';
        return;
      } else if (lowerCmd.includes('about')) {
         response = 'IDENTITY: Rajeet Nair\nROLE: Generative AI Engineer\nFOCUS: Agentic Systems, Production RAG, and AI Automation.\nSTATUS: Online and Ready for Deployment.';
      } else if (lowerCmd.includes('projects')) {
         response = 'Retrieving Project Database...\n\n1. Nosta Social AI Agent\n2. Nosta Multi-RAG + OCR\n3. Invoice OCR & Cost Agent\n4. ML Warehouse Ops\n\nRun "project [id]" for details (simulated).';
      } else if (lowerCmd.includes('contact')) {
         response = 'COMMUNICATION CHANNELS:\n\n- Email: contact@rajeetnair.com\n- Location: Mumbai, India';
      } else {
        response = `Command "${cleanCmd}" processed.\n\nAutomated Response: Rajeet is currently in deep work mode building production systems. For urgent inquiries, please utilize the direct email channel.`;
      }

      setHistory(prev => [...prev, { type: 'ai', content: response }]);
      setIsTyping(false);
    }, 600);
  };

  return (
    <div className="fixed inset-0 z-[60] bg-[#050505] text-[#EAEAEA] font-mono flex flex-col p-4 md:p-8 overflow-hidden selection:bg-accent selection:text-black touch-manipulation">
      {/* CRT Scanline Effect - Optimized for mobile */}
      <div className="absolute inset-0 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] z-10 pointer-events-none bg-[length:100%_2px,3px_100%] opacity-20 transform-gpu"></div>

      {/* Header */}
      <div className="flex justify-between items-center mb-4 border-b border-white/10 pb-2 z-20 shrink-0">
        <div className="flex items-center gap-2 text-accent">
          <TerminalIcon size={16} />
          <span className="text-xs tracking-widest uppercase">Bash // Remote_Session</span>
        </div>
        <Link to="/" className="text-textMuted hover:text-accent transition-colors p-2 -mr-2">
          <X size={20} />
        </Link>
      </div>

      {/* Terminal Output */}
      <div className="flex-grow overflow-y-auto no-scrollbar space-y-2 mb-4 relative z-20 font-mono text-sm md:text-base overscroll-y-contain" onClick={() => inputRef.current?.focus()}>
        {history.map((entry, idx) => (
          <div key={idx} className={`${entry.type === 'system' ? 'text-accentDim text-xs mt-4 mb-2' : entry.type === 'user' ? 'text-textMain mt-4' : 'text-accent/90'} whitespace-pre-wrap leading-relaxed`}>
            {entry.type === 'user' ? (
              <span className="flex gap-2">
                <span className="text-accent select-none">visitor@nair:~$</span>
                <span>{entry.content}</span>
              </span>
            ) : entry.type === 'system' ? (
               <span>{`>> ${entry.content}`}</span>
            ) : (
              <span className="block">{entry.content}</span>
            )}
          </div>
        ))}
        {isTyping && (
           <div className="text-accentDim text-xs animate-pulse mt-2">_ Processing...</div>
        )}
        <div ref={scrollRef}></div>
      </div>

      {/* Input Line */}
      <div className="flex items-center gap-2 relative z-20 border-t border-white/10 pt-4 shrink-0">
        <span className="text-accent select-none font-bold text-base md:text-lg">visitor@nair:~$</span>
        <input 
          ref={inputRef}
          type="text" 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') handleCommand(input);
          }}
          className="flex-grow bg-transparent border-none outline-none text-textMain caret-accent font-mono text-base md:text-lg"
          autoFocus
          spellCheck={false}
          autoComplete="off"
        />
      </div>
    </div>
  );
};

