const ScrollToTop = () => {
  const { pathname } = useLocation();
  React.useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

// Optimized Boot Sequence
const BootSequence = ({ onComplete }: { onComplete: () => void }) => {
  const [steps, setSteps] = useState<string[]>([]);

  useEffect(() => {
    const sequence = [
      "INITIALIZING KERNEL...",
      "LOADING SYSTEM MODULES...",
      "CONNECTING TO DATABASE...",
      "UI OPTIMIZED.",
      "WELCOME, VISITOR."
    ];

    let delay = 0;
    const timeouts: ReturnType<typeof setTimeout>[] = [];

    sequence.forEach((step, index) => {
      delay += Math.random() * 60 + 30; 
      const id = setTimeout(() => {
        setSteps(prev => [...prev, step]);
        if (index === sequence.length - 1) {
          setTimeout(onComplete, 150);
        }
      }, delay);
      timeouts.push(id);
    });

    return () => timeouts.forEach(clearTimeout);
  }, [onComplete]);

  return (
    <div className="fixed inset-0 bg-background z-[1000] flex flex-col items-center justify-center font-mono text-accent">
       <div className="w-64">
          <div className="flex justify-between items-center mb-4 border-b border-accent/30 pb-2">
             <span className="text-xs tracking-widest">BOOT_SEQ_V2.1</span>
             <Loader2 className="animate-spin" size={14} />
          </div>
          <div className="space-y-2 h-32">
            {steps.map((step, i) => (
              <div key={i} className="text-sm typing-effect opacity-80">> {step}</div>
            ))}
          </div>
          <div className="mt-4 h-1 w-full bg-surface relative overflow-hidden">
             <div className="absolute inset-0 bg-accent animate-progress-bar"></div>
          </div>
       </div>
    </div>
  );
};

// Minimal loading fallback
const PageLoader = () => (
    <div className="min-h-[50vh] flex items-center justify-center text-accent">
        <Loader2 className="animate-spin" size={32} />
    </div>
);

function App() {
  const [isLoading, setIsLoading] = useState(true);
  const [isChatOpen, setIsChatOpen] = useState(false);

  if (isLoading) {
    return <BootSequence onComplete={() => setIsLoading(false)} />;
  }

  return (
    <Router>
        <div className="min-h-screen bg-background text-textMain font-sans selection:bg-accent selection:text-black relative">

          <div className="fixed inset-0 bg-noise z-50 mix-blend-overlay pointer-events-none opacity-40"></div>
          <div className="fixed inset-0 bg-grid-pattern opacity-[0.05] pointer-events-none z-0"></div>

          <ScrollToTop />
          <Navbar onOpenTerminal={() => setIsChatOpen(true)} />

          <main className="relative z-10 pl-0 transition-opacity duration-1000 animate-fade-in">
            <Suspense fallback={<PageLoader />}>
                <Routes>
                    <Route path="/" element={<Home />} />
                    <Route path="/overview" element={<Overview />} />
                    <Route path="/about" element={<About />} />
                    <Route path="/work" element={<Work />} />
                    <Route path="/projects" element={<ProjectsPage />} />
                    <Route path="/project/:id" element={<ProjectDetail />} />
                    <Route path="/code" element={<CodeVault />} />
                    <Route path="/certs" element={<CertsPage />} />
                    <Route path="/automation" element={<Automation />} />
                </Routes>
            </Suspense>
          </main>

          <Footer />

          {/* Global Terminal Overlay */}
          <ChatOverlay isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} />

          {/* Floating Action Button - Toggles Terminal */}
          <button 
            onClick={() => setIsChatOpen(prev => !prev)}
            className="fixed bottom-8 right-8 z-[90] w-14 h-14 bg-accent rounded-full flex items-center justify-center shadow-[0_0_20px_rgba(76,169,255,0.4)] hover:scale-110 transition-transform group"
            aria-label="Open Terminal"
          >
              <div className="absolute inset-0 rounded-full border border-white/20 animate-ping opacity-20"></div>
              <MessageSquare size={24} className="text-background group-hover:text-white transition-colors" />
          </button>
        </div>
    </Router>
  );
}

