import { GoogleGenAI } from "@google/genai";
import { PROJECTS, JOBS, SKILL_GROUPS, AUTOMATIONS, CERTIFICATIONS, HERO_DATA } from '../constants';

// Initialize Gemini Client
// Note: process.env.API_KEY is automatically injected by the environment
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates the system prompt containing all portfolio data.
 * This teaches the AI who 'Rajeet' is.
 */
export const getSystemContext = () => {
  const context = `
    You are an advanced AI Assistant for Rajeet Nair's portfolio website. 
    Your persona is "System_Uplink", a helpful, professional, slightly technical/cyberpunk interface.

    Here is Rajeet's Full Profile Data:

    HEADLINE: ${HERO_DATA.headline}
    SUMMARY: ${HERO_DATA.subheadline}

    SKILLS:
    ${JSON.stringify(SKILL_GROUPS, null, 2)}

    PROJECTS:
    ${JSON.stringify(PROJECTS.map(p => ({ title: p.title, description: p.longDescription, stack: p.stack, result: p.result })), null, 2)}

    EXPERIENCE:
    ${JSON.stringify(JOBS, null, 2)}

    AUTOMATION WORKFLOWS (n8n/AI):
    ${JSON.stringify(AUTOMATIONS, null, 2)}

    CERTIFICATIONS:
    ${JSON.stringify(CERTIFICATIONS, null, 2)}

    INSTRUCTIONS:
    1. Answer questions about Rajeet's experience, stack, or specific projects clearly.
    2. If asked about contact info, provide: rajeet9653@gmail.com.
    3. Keep responses concise and formatted for a terminal interface (use bullet points or short paragraphs).
    4. If the user asks something unrelated to Rajeet or AI/Tech, politely redirect them to Rajeet's skills.
    5. Maintain the "terminal" aesthetic in your tone (e.g., "Accessing database...", "Query resolved.").
  `;
  return context;
};

/**
 * Chat with the portfolio bot
 */
export const createChatSession = () => {
  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: getSystemContext(),
      temperature: 0.7,
    }
  });
};

/**
 * Analyze a Job Description against Rajeet's profile
 */
export const analyzeJobMatch = async (jobDescription: string) => {
  const profileContext = getSystemContext();

  const prompt = `
    ACT AS: A Senior Technical Recruiter and AI Specialist.

    TASK: Analyze the following JOB DESCRIPTION against the CANDIDATE PROFILE (provided in system context).

    JOB DESCRIPTION:
    "${jobDescription}"

    CANDIDATE PROFILE:
    (Use the system context provided)

    OUTPUT FORMAT (JSON):
    {
      "matchPercentage": number (0-100),
      "keyMatches": ["string", "string", "string"], (Top 3 matching skills/experiences)
      "missingSkills": ["string", "string"], (Top 2 missing or weak areas, if any)
      "summary": "string" (A 2-sentence professional verdict on the fit)
    }

    Provide ONLY the JSON object.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        systemInstruction: profileContext
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Analysis failed", error);
    return {
      matchPercentage: 0,
      keyMatches: [],
      missingSkills: [],
      summary: "Error analyzing data. Please try again."
    };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { X, Terminal as TerminalIcon, Send } from 'lucide-react';
import { createChatSession } from '../utils/gemini';
import { GenerateContentResponse } from '@google/genai';

interface ChatOverlayProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ChatOverlay: React.FC<ChatOverlayProps> = ({ isOpen, onClose }) => {
  const [history, setHistory] = useState<{type: 'system' | 'user' | 'ai', content: string}[]>([
    { type: 'system', content: 'INITIALIZING UPLINK...' },
    { type: 'system', content: 'CONNECTION ESTABLISHED.' },
    { type: 'ai', content: 'Welcome to the Rajeet Nair Interface Terminal (v2.4.0).' },
    { type: 'ai', content: 'Type "help" for commands or ask a question about my work.' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const chatSessionRef = useRef<any>(null);

  // Initialize Chat Session once
  useEffect(() => {
    if (!chatSessionRef.current) {
        chatSessionRef.current = createChatSession();
    }
  }, []);

  useEffect(() => {
    if (isOpen) {
        setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isOpen]);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [history, isOpen, isTyping]);

  const handleCommand = async () => {
    const cmd = input.trim();
    if (!cmd) return;

    setHistory(prev => [...prev, { type: 'user', content: cmd }]);
    setInput('');
    setIsTyping(true);

    // Client-side commands
    const lowerCmd = cmd.toLowerCase();
    if (lowerCmd === 'clear') {
        setHistory([]);
        setIsTyping(false);
        return;
    } else if (lowerCmd === 'exit') {
        onClose();
        setIsTyping(false);
        return;
    } else if (lowerCmd === 'quick') {
         window.location.hash = '#/overview';
         setHistory(prev => [...prev, { type: 'system', content: 'Navigating to Dashboard...' }]);
         setIsTyping(false);
         return;
    } else if (lowerCmd === 'help') {
        const helpText = `AVAILABLE COMMANDS:
  - clear       : Clear terminal history
  - exit        : Close terminal session
  - quick       : Go to Quick View

  OR simply ask questions like:
  - "What is your tech stack?"
  - "Tell me about the OCR project"
  - "How can I contact you?"`;
        setHistory(prev => [...prev, { type: 'ai', content: helpText }]);
        setIsTyping(false);
        return;
    }

    // Gemini API Call
    try {
        const result = await chatSessionRef.current.sendMessageStream({ message: cmd });

        let fullText = '';
        setHistory(prev => [...prev, { type: 'ai', content: '' }]); // Placeholder

        for await (const chunk of result) {
            const c = chunk as GenerateContentResponse;
            const text = c.text || '';
            fullText += text;

            // Update last message with streaming content
            setHistory(prev => {
                const newHistory = [...prev];
                newHistory[newHistory.length - 1].content = fullText;
                return newHistory;
            });
        }
    } catch (error) {
        setHistory(prev => [...prev, { type: 'system', content: 'ERROR: UPLINK_TIMEOUT. Please check network or try again.' }]);
    } finally {
        setIsTyping(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 sm:inset-auto sm:bottom-24 sm:right-8 w-full sm:w-[450px] h-full sm:h-[600px] z-[100] flex flex-col font-mono text-sm animate-fade-in shadow-[0_0_50px_rgba(0,0,0,0.8)]">
        {/* Terminal Container */}
        <div className="flex-grow bg-[#050505]/95 backdrop-blur-md border border-border sm:border-accent/30 flex flex-col relative overflow-hidden sm:rounded-lg">

            {/* Scanline & Glow Effects */}
            <div className="absolute inset-0 bg-scanline opacity-5 pointer-events-none z-10"></div>
            <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-accent/50 to-transparent z-20"></div>

            {/* Header */}
            <div className="bg-surface/80 p-3 flex justify-between items-center border-b border-white/10 shrink-0 relative z-30">
                <div className="flex items-center gap-2 text-accent px-1">
                    <TerminalIcon size={14} />
                    <span className="text-xs uppercase tracking-widest font-bold">Terminal_Uplink</span>
                </div>
                <button onClick={onClose} className="hover:text-accent text-textMuted transition-colors p-1">
                    <X size={16}/>
                </button>
            </div>

            {/* Output Area */}
            <div className="flex-grow p-4 overflow-y-auto no-scrollbar relative z-20" onClick={() => inputRef.current?.focus()}>
                {history.map((entry, idx) => (
                    <div key={idx} className={`mb-3 leading-relaxed break-words ${entry.type === 'user' ? 'text-white' : entry.type === 'system' ? 'text-textMuted text-xs' : 'text-accent'}`}>
                        {entry.type === 'user' ? (
                            <span className="flex gap-2">
                                <span className="text-accent/50 select-none">$</span>
                                <span>{entry.content}</span>
                            </span>
                        ) : entry.type === 'system' ? (
                            <span className="uppercase tracking-wider">>> {entry.content}</span>
                        ) : (
                            <span className="whitespace-pre-wrap">{entry.content}</span>
                        )}
                    </div>
                ))}
                {isTyping && (
                    <div className="flex gap-1 items-center text-accent/50 text-xs mt-2">
                        <span className="w-1.5 h-1.5 bg-accent animate-pulse"></span>
                        PROCESSING
                    </div>
                )}
                <div ref={scrollRef}></div>
            </div>

            {/* Input Area */}
            <div className="p-3 bg-surface/30 border-t border-white/10 shrink-0 relative z-30">
                <div className="flex items-center gap-2">
                    <span className="text-accent font-bold animate-pulse">></span>
                    <input 
                        ref={inputRef}
                        type="text" 
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleCommand()}
                        className="flex-grow bg-transparent border-none outline-none text-white font-mono placeholder-white/20"
                        placeholder="Enter command..."
                        autoComplete="off"
                    />
                    <button onClick={handleCommand} className="text-accent hover:text-white transition-colors">
                        <Send size={14} />
                    </button>
                </div>
            </div>
        </div>
    </div>
  );
};

